        console.log("[处理] 正在分析第 " + num + " / " + total + " 题");
        let raw = el.innerText || el.textContent;
        console.log("[调试] 原始 innerText: " + JSON.stringify(raw.substring(0, 80)));
        let questionVariants = extractQuestionVariants(el);
        let qText = questionVariants[0] || '';
        console.log("[调试] 题干候选提取结果: " + JSON.stringify(qText.substring(0, 120))
            + " (innerText=" + String(el.innerText || '').length
            + ", textContent=" + String(el.textContent || '').length
            + ", candidates=" + questionVariants.length + ")");
